import java.util.Scanner;

public class Main {
    static final long MODULUS = 1000000007;

    static long modPow(long base, long exponent) {
        long result = 1;
        for (int i = 0; i < exponent; i++) {
            result = (result * base) % MODULUS;
        }
        return result;
    }

    static long findSolution(long p, long k) {
        if (k <= 1) {
            return modPow(p, p - 1 + k);
        }
        int orderCount = 1;
        long val = k;
        while (val != 1) {
            val = (val * k) % p;
            orderCount++;
        }
        return modPow(p, (p - 1) / orderCount);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long p = scanner.nextLong();
        long k = scanner.nextLong();
        System.out.println(findSolution(p, k));
        scanner.close();
    }
}
